/// <summary>
/// Contract class for <c>METPaymentStatusUpdateService</c>
/// </summary>
[DataContractAttribute('paymentStatusUpdate')]
public class METPaymentStatusUpdateContract
{

    DataAreaId                                  dataAreaId;
    Filename                                    fileName;

}

Method.Source:
    /// <summary>
    /// Gets or sets the <c>dataAreaId</c> parameter.
    /// </summary>
    /// <param name = "_dataAreaId">The value to set.</param>
    /// <returns>The value of the <c>dataAreaId</c> parameter.</returns>
    [DataMemberAttribute('dataAreaId')]
    public DataAreaId parmDataAreaId(DataAreaId  _dataAreaId = dataAreaId)
    {
        dataAreaId = _dataAreaId;

        return dataAreaId;
    }

/// <summary>
/// Gets or sets the <c>fileName</c> parameter.
/// </summary>
/// <param name = "_fileName">The value to set.</param>
/// <returns>The value of the fileName parameter.</returns>
[DataMemberAttribute('fileName')]
public Filename parmFileName(Filename _fileName = fileName)
{
    fileName = _fileName;
    
    return fileName;
}
